}

/* Modern notice heading */
.nu-modern-notice-section .nu-notice-board-header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 180px;
    align-items: stretch;
    overflow: hidden;
    margin: 0 0 12px;
    border: 1px solid rgba(63, 154, 214, 0.38);
