    font-weight: 800;
    text-align: center;
}

.nu-modern-notice-section .nu-notice-header-date .fa {
    color: #3F9AD6;
    font-size: 16px;
}

/* Draggable notice viewport */
.nu-modern-notice-section .nu-modern-notice-scroll {
    position: relative;
    width: 100%;
    height: min(70vh, 750px) !important;
    min-height: 430px;
    padding: 5px 8px 12px;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    border: 1px solid #dce9f1;
    border-radius: 14px;
    background:
        linear-gradient(180deg, #f7fbfe 0%, #ffffff 100%);
    box-shadow:
        inset 0 1px 4px rgba(31, 75, 105, 0.06),
        0 6px 18px rgba(31, 75, 105, 0.08);
    cursor: grab;
    user-select: none;
    overscroll-behavior: contain;
    scroll-behavior: smooth;
    scrollbar-width: thin;
    scrollbar-color: #3F9AD6 #e8f3fa;
}

.nu-modern-notice-section .nu-modern-notice-scroll.is-dragging {
    cursor: grabbing;
    scroll-behavior: auto;
}

.nu-modern-notice-section .nu-modern-notice-scroll::-webkit-scrollbar {
    width: 10px;
}

.nu-modern-notice-section .nu-modern-notice-scroll::-webkit-scrollbar-track {
    border-radius: 10px;
    background-color: #e8f3fa;
}

.nu-modern-notice-section .nu-modern-notice-scroll::-webkit-scrollbar-thumb {
    border: 2px solid #e8f3fa;
    border-radius: 10px;
    background:
        linear-gradient(180deg, #64afe0 0%, #3F9AD6 100%);
}

.nu-modern-notice-section .nu-modern-notice-scroll::-webkit-scrollbar-thumb:hover {
    background:
        linear-gradient(180deg, #3F9AD6 0%, #2479B2 100%);
}

/* Tables generated by tab-latest-notice.php */
.nu-modern-notice-section .nu-modern-notice-scroll table {
    width: 100% !important;
    margin: 0 !important;
    border: 0 !important;
