}

.nu-modern-notice-section .nu-modern-notice-scroll tbody {
    background: transparent !important;
}

.nu-modern-notice-section .nu-modern-notice-scroll tr.nu-modern-notice-row,
.nu-modern-notice-section .nu-modern-notice-scroll table tr {
    position: relative;
    background-color: transparent !important;
}

.nu-modern-notice-section .nu-modern-notice-scroll table td {
    padding: 13px 15px !important;
