    border-bottom: 1px solid #dce9f1 !important;
    background-color: #ffffff !important;
    vertical-align: middle !important;
    box-shadow: 0 4px 13px rgba(31, 75, 105, 0.08);
    transition:
        background-color 0.25s ease,
        border-color 0.25s ease,
        box-shadow 0.25s ease,
        transform 0.25s ease;
}

.nu-modern-notice-section .nu-modern-notice-scroll table td:first-child {
    border-left: 4px solid var(--notice-color, #3F9AD6) !important;
    border-radius: 11px 0 0 11px;
}

.nu-modern-notice-section .nu-modern-notice-scroll table td:last-child {
    border-right: 1px solid #dce9f1 !important;
    border-radius: 0 11px 11px 0;
}

.nu-modern-notice-section .nu-modern-notice-scroll table tr:hover td {
    border-color: rgba(63, 154, 214, 0.52) !important;
    background-color: #f8fcff !important;
    box-shadow: 0 8px 18px rgba(31, 75, 105, 0.14);
    transform: translateY(-2px);
}

/* Different title colours in a repeating pattern */
.nu-modern-notice-section .nu-modern-notice-scroll table tr:nth-child(4n + 1) {
    --notice-color: #2479B2;
}

.nu-modern-notice-section .nu-modern-notice-scroll table tr:nth-child(4n + 2) {
    --notice-color: #168A72;
}

.nu-modern-notice-section .nu-modern-notice-scroll table tr:nth-child(4n + 3) {
    --notice-color: #9A62B0;
}

.nu-modern-notice-section .nu-modern-notice-scroll table tr:nth-child(4n + 4) {
    --notice-color: #C56A25;
}

.nu-modern-notice-section .nu-modern-notice-scroll table td:first-child a,
.nu-modern-notice-section .nu-modern-notice-scroll .nu-notice-title-link {
    color: var(--notice-color, #2479B2) !important;
    font-size: 14px;
    font-weight: 700 !important;
    line-height: 1.62;
    text-decoration: none !important;
    transition: color 0.25s ease;
}

.nu-modern-notice-section .nu-modern-notice-scroll table td:first-child a:hover,
.nu-modern-notice-section .nu-modern-notice-scroll table td:first-child a:focus {
    color: #153F5B !important;
    text-decoration: none !important;
}

/* Stylish publish date */
.nu-modern-notice-section .nu-modern-notice-scroll .nu-notice-date-cell,
.nu-modern-notice-section .nu-modern-notice-scroll table td:last-child {
    width: 175px;
    color: #365F7C !important;
    font-size: 12px;
    font-weight: 800 !important;
    text-align: center !important;
    white-space: normal;
}

.nu-modern-notice-section .nu-notice-date-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-width: 122px;
    padding: 7px 11px;
    border: 1px solid rgba(63, 154, 214, 0.32);
    border-radius: 20px;
    background:
        linear-gradient(180deg, #ffffff 0%, #eaf5fc 100%);
    color: #2479B2;
    font-size: 12px;
    font-weight: 800;
    line-height: 1.35;
    box-shadow: 0 3px 9px rgba(63, 154, 214, 0.12);
}

.nu-modern-notice-section .nu-notice-date-badge .fa {
    color: #3F9AD6;
}

/* Fallback styling when included notices are not in a table */
.nu-modern-notice-section .nu-modern-notice-scroll > ul,
.nu-modern-notice-section .nu-modern-notice-scroll > ol {
    margin: 0;
    padding: 0;
