        border-color .24s ease,
        box-shadow .24s ease,
        transform .24s ease;
}

/* Title is now first column */
.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(1) {
    width: auto;
    border-left: 4px solid var(--notice-color) !important;
    border-radius: 11px 0 0 11px;
}

.nu-recent-news-notice-section .news-item {
    margin: 0;
}

.nu-recent-news-notice-section .news-item a {
    display: block;
    color: var(--notice-color, #2479B2) !important;
    font-size: 14px;
    font-weight: 700 !important;
    line-height: 1.62;
    text-decoration: none !important;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.nu-recent-news-notice-section .news-item a:hover,
.nu-recent-news-notice-section .news-item a:focus {
    color: #153F5B !important;
}

/* Post date is second column */
.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(2) {
    width: 182px;
    text-align: center !important;
}

.nu-recent-news-notice-section .dated-document {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-width: 130px;
    padding: 7px 11px;
    border: 1px solid rgba(63, 154, 214, .32);
    border-radius: 20px;
    background:
        linear-gradient(180deg, #FFFFFF 0%, #EAF5FC 100%);
    color: var(--nu-blue-dark) !important;
    font-size: 12px;
    font-weight: 800 !important;
    line-height: 1.35;
    box-shadow: 0 3px 9px rgba(63, 154, 214, .12);
}

.nu-recent-news-notice-section .dated-document::before {
    color: var(--nu-blue);
    content: "\f073";
    font-family: FontAwesome;
    font-size: 12px;
    font-weight: normal;
}

/* Download is third column */
.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) {
    width: 80px;
    border-right: 1px solid var(--nu-border) !important;
    border-radius: 0 11px 11px 0;
    text-align: center !important;
}

.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 41px;
    height: 41px;
    overflow: hidden;
    border: 1px solid var(--nu-purple);
    border-radius: 50%;
    background: var(--nu-purple);
    box-shadow: 0 4px 11px rgba(103, 50, 186, .20);
    transition:
        background-color .2s ease,
        transform .2s ease,
        box-shadow .2s ease;
}

.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) a:hover,
.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) a:focus {
    background: #FFFFFF;
    transform: translateY(-2px);
    box-shadow: 0 7px 15px rgba(103, 50, 186, .28);
}

.nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) img {
    display: block;
    width: 21px !important;
    height: 21px !important;
    max-width: 21px !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 2px;
    object-fit: cover;
}

.nu-recent-news-notice-section .nu-recent-notice-table tr:hover td {
    border-color: rgba(63, 154, 214, .52) !important;
    background: #F8FCFF !important;
    box-shadow: 0 8px 18px rgba(31, 75, 105, .14);
    transform: translateY(-2px);
}

/* Pagination/search visibility */
.nu-recent-news-notice-section .nu-recent-notice-table tr.nu-page-hidden,
.nu-recent-news-notice-section .nu-recent-notice-table tr.nu-search-hidden {
    display: none !important;
}

.nu-recent-empty-state {
    display: none;
    margin: 12px 4px;
    padding: 30px 18px;
    border: 1px dashed #BAD5E5;
    border-radius: 14px;
    background: #FFFFFF;
    color: #607B8C;
    font-size: 13px;
    font-weight: 700;
    text-align: center;
}

.nu-recent-empty-state.is-visible {
    display: block;
}

/* =========================================================
   Modern stylish pagination
   ========================================================= */
.nu-recent-pagination-wrap {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 13px;
    margin-top: 13px;
    padding: 12px 13px;
    border: 1px solid rgba(63, 154, 214, .30);
    border-radius: 15px;
    background:
        linear-gradient(180deg, #FFFFFF 0%, #F5FAFD 100%);
    box-shadow: 0 6px 17px rgba(31, 75, 105, .09);
}

.nu-recent-pagination-summary {
    color: #6C8190;
    font-size: 10.5px;
    font-weight: 800;
    white-space: nowrap;
}

.nu-recent-pagination {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 5px;
    flex-wrap: wrap;
}

.nu-page-btn,
.nu-page-ellipsis {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    height: 36px;
    padding: 0 10px;
    border-radius: 18px;
    font-size: 11px;
    font-weight: 800;
    line-height: 1;
}

.nu-page-btn {
    border: 1px solid #CEE0EB;
    background: #FFFFFF;
    color: #466779;
    cursor: pointer;
    box-shadow: 0 3px 8px rgba(31, 75, 105, .06);
    transition:
        color .2s ease,
        border-color .2s ease,
        background-color .2s ease,
        transform .2s ease,
        box-shadow .2s ease;
}

.nu-page-btn:hover,
.nu-page-btn:focus {
    border-color: var(--nu-blue);
    background: #EAF5FC;
    color: var(--nu-blue-dark);
    transform: translateY(-2px);
    box-shadow: 0 5px 11px rgba(63, 154, 214, .14);
    outline: 0;
}

.nu-page-btn.is-active {
    border-color: var(--nu-blue);
    background:
        linear-gradient(135deg, var(--nu-blue) 0%, var(--nu-blue-dark) 100%);
    color: #FFFFFF;
    box-shadow: 0 5px 13px rgba(63, 154, 214, .28);
    cursor: default;
}

.nu-page-btn.nu-page-nav {
    min-width: 39px;
    padding: 0 11px;
    color: var(--nu-purple);
}

.nu-page-btn.nu-page-nav:hover,
.nu-page-btn.nu-page-nav:focus {
    border-color: var(--nu-purple);
    background: #F3EEFA;
    color: var(--nu-purple);
}

.nu-page-btn:disabled {
    opacity: .40;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none;
}

.nu-page-ellipsis {
    min-width: 24px;
    padding: 0 3px;
    color: #8A9AA5;
}

/* Tablet */
@media (max-width: 991px) {
    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(2) {
        width: 158px;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) {
        width: 68px;
    }

    .nu-recent-pagination-wrap {
        align-items: flex-start;
        flex-direction: column;
    }

    .nu-recent-pagination {
        justify-content: flex-start;
    }
}

/* Mobile / iPhone / small tablet */
@media (max-width: 767px) {
    .nu-recent-toolbar {
        align-items: stretch;
        flex-direction: column;
        padding: 10px;
    }

    .nu-recent-search-box {
        flex-basis: auto;
        width: 100%;
        max-width: none;
    }

    .nu-recent-toolbar-meta {
        justify-content: flex-start;
    }

    .nu-recent-news-notice-section .nu-recent-notice-scroll {
        padding: 4px 5px 8px;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table,
    .nu-recent-news-notice-section .nu-recent-notice-table tbody,
    .nu-recent-news-notice-section .nu-recent-notice-table tr,
    .nu-recent-news-notice-section .nu-recent-notice-table td {
        display: block;
        width: 100% !important;
        box-sizing: border-box;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table {
        border-spacing: 0 !important;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table tr {
        position: relative;
        margin: 9px 0;
        padding: 13px 12px 58px;
        overflow: hidden;
        border: 1px solid var(--nu-border);
        border-left: 4px solid var(--notice-color, var(--nu-blue));
        border-radius: 12px;
        background: #FFFFFF !important;
        box-shadow: 0 4px 13px rgba(31, 75, 105, .08);
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td,
    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(1),
    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(2),
    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) {
        padding: 0 !important;
        border: 0 !important;
        border-radius: 0;
        background: transparent !important;
        box-shadow: none !important;
        transform: none !important;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(1) {
        margin-bottom: 12px;
    }

    .nu-recent-news-notice-section .news-item a {
        font-size: 13px;
        line-height: 1.65;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(2) {
        position: absolute;
        left: 12px;
        bottom: 12px;
        width: auto !important;
        max-width: calc(100% - 65px);
        text-align: left !important;
    }

    .nu-recent-news-notice-section .dated-document {
        min-width: 0;
        padding: 6px 10px;
        font-size: 10.5px;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) {
        position: absolute;
        right: 11px;
        bottom: 10px;
        width: 40px !important;
    }

    .nu-recent-news-notice-section .nu-recent-notice-table td:nth-child(3) a {
        width: 37px;
        height: 37px;
    }

    .nu-recent-pagination-wrap {
        padding: 11px 10px;
    }

    .nu-recent-pagination {
        width: 100%;
        gap: 4px;
    }

    .nu-page-btn {
        min-width: 34px;
        height: 34px;
        padding: 0 9px;
    }
}

@media (max-width: 480px) {
    .nu-recent-page-info,
    .nu-recent-clear-btn {
        flex: 1 1 auto;
    }

    .nu-recent-pagination-summary {
        width: 100%;
        white-space: normal;
    }

    .nu-page-btn {
        min-width: 32px;
        height: 32px;
        padding: 0 8px;
        font-size: 10.5px;
    }

    .nu-page-btn.nu-page-nav {
        min-width: 34px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .nu-recent-news-notice-section *,
    .nu-recent-news-notice-section *::before,
    .nu-recent-news-notice-section *::after {
        transition: none !important;
        scroll-behavior: auto !important;
    }
}
