 <tr>
  <td><div class="news-item"><a target="_blank" rel="noopener noreferrer" href="uploads/notices/notice_4158_pub_date_19122025.pdf">রাষ্ট্রীয় শোক পালনের অংশ হিসেবে আগামীকাল ২০ ডিসেম্বর ২০২৫ তারিখ শনিবার জাতীয় বিশ্ববিদ্যালয়ের গাজীপুর ক্যাম্পাস, নগর কার্যালয় ও আঞ্চলিক কেন্দ্রসমূহে জাতীয় পতাকা এবং জাতীয় বিশ্ববিদ্যালয়ের পতাকা অর্ধনমিত থাকবে এবং রাষ্ট্রীয় শোক পালনের পরিপ্রেক্ষিতে পূর্ব নির্ধারিত জাতীয় বিশ্ববিদ্যালয়ের বিশেষ সিনেট অধিবেশন পুনঃনির্ধারণ ও অফিস কার্যক্রম বন্ধ সংক্রান্ত অফিস আদেশ। </a></div></td>
