 <tr>
  <td><div class="news-item"><a target="_blank" rel="noopener noreferrer" href="uploads/notices/notice_10964_pub_date_09072024.pdf">২০২৩ সালের বি.এসসি অনার্স ইন-কম্পিউটার সায়েন্স এন্ড ইঞ্জিনিয়ারিং (CSE), বি.এসসি অনার্স ইন-এ্যাপারেল ম্যানুফেকচার এন্ড টেকনোলজি (AMT), নীটওয়্যার ম্যানুফেকচার এন্ড টেকনোলজি (KMT) এবং ফ্যাশন ডিজাইন এন্ড টেকনোলজি (FDT), বি.এসসি অনার্স ইন- ইলেক্ট্রনিক্স এন্ড কমিউনিকেশন ইঞ্জিনিয়ারিং (ECE), বিবিএ (প্রফেশনাল), বিবিএ (অনার্স) ইন- ট্যুরিজম এন্ড হসপিটালিটি ম্যানেজমেন্ট (THM) এবং বিএড (অনার্স) প্রথম বর্ষ ১ম সেমিস্টার  ( নতুন ও পুরাতন সিলেবাস অনুযায়ী ) পরীক্ষার জন্য EMS Software এর Center Panel এবং Invigilator App পরিচালনা, হাজিরা প্রেরণ ও অন্যান্য আনুসাঙ্গিক নির্দেশাবলী। </a></div></td>
