<script>
(function initialiseRecentNoticePagination(){
'use strict';
var table=document.getElementById('nuRecentNoticeTable'),pagination=document.getElementById('nuRecentPagination'),summary=document.getElementById('nuRecentPaginationSummary'),pageInfo=document.getElementById('nuRecentPageInfo'),searchInput=document.getElementById('nuRecentSearch'),clearButton=document.getElementById('nuRecentClearSearch'),emptyState=document.getElementById('nuRecentEmptyState');
if(!table||!pagination||table.getAttribute('data-pagination-ready')==='1')return;
table.setAttribute('data-pagination-ready','1');
var tbody=table.tBodies.length?table.tBodies[0]:null;if(!tbody)return;
var pageSize=20,currentPage=1,searchTimer=null,sourceRows=[],allRows=[],filteredRows=[],archiveReady=false;
var INDEX_BATCH_SIZE=160,INITIAL_PREPARE_DELAY=40;
function idle(cb){if(typeof window.requestIdleCallback==='function'){window.requestIdleCallback(cb,{timeout:100});}else{window.setTimeout(cb,0);}}
function button(label,page,cls,disabled,active,aria){var b=document.createElement('button');b.type='button';b.className='nu-page-btn'+(cls?' '+cls:'');b.innerHTML=label;b.disabled=!!disabled;if(active){b.classList.add('is-active');b.setAttribute('aria-current','page');}if(aria)b.setAttribute('aria-label',aria);if(!disabled&&!active&&page)b.addEventListener('click',function(){showPage(page,true);});return b;}
function ellipsis(){var s=document.createElement('span');s.className='nu-page-ellipsis';s.setAttribute('aria-hidden','true');s.textContent='...';pagination.appendChild(s);}
function buildPagination(totalPages){pagination.innerHTML='';if(totalPages<=1)return;pagination.appendChild(button('<i class="fa fa-angle-double-left" aria-hidden="true"></i>',1,'nu-page-nav',currentPage===1,false,'First page'));pagination.appendChild(button('<i class="fa fa-angle-left" aria-hidden="true"></i>',currentPage-1,'nu-page-nav',currentPage===1,false,'Previous page'));var pages=[],start=Math.max(1,currentPage-2),end=Math.min(totalPages,currentPage+2);if(currentPage<=3)end=Math.min(totalPages,5);if(currentPage>=totalPages-2)start=Math.max(1,totalPages-4);if(start>1)pages.push(1);for(var i=start;i<=end;i++){if(pages.indexOf(i)===-1)pages.push(i);}if(end<totalPages&&pages.indexOf(totalPages)===-1)pages.push(totalPages);var prev=0;pages.forEach(function(p){if(prev&&p-prev>1)ellipsis();pagination.appendChild(button(String(p),p,'',false,p===currentPage,'Page '+p));prev=p;});pagination.appendChild(button('<i class="fa fa-angle-right" aria-hidden="true"></i>',currentPage+1,'nu-page-nav',currentPage===totalPages,false,'Next page'));pagination.appendChild(button('<i class="fa fa-angle-double-right" aria-hidden="true"></i>',totalPages,'nu-page-nav',currentPage===totalPages,false,'Last page'));}
function mount(rows){var f=document.createDocumentFragment();rows.forEach(function(r){r.classList.remove('nu-search-hidden','nu-page-hidden');f.appendChild(r);});while(tbody.firstChild)tbody.removeChild(tbody.firstChild);tbody.appendChild(f);}
function showPage(page,scroll){if(!archiveReady)return;var total=filteredRows.length,pages=Math.max(1,Math.ceil(total/pageSize));currentPage=Math.max(1,Math.min(page,pages));var start=(currentPage-1)*pageSize,end=Math.min(start+pageSize,total);mount(filteredRows.slice(start,end));if(emptyState)emptyState.classList.toggle('is-visible',total===0);if(pageInfo)pageInfo.textContent=total===0?'0 notices':'Showing '+(start+1)+'–'+end+' of '+total;if(summary)summary.textContent='Page '+currentPage+' of '+pages+' • Maximum 20 notices per page';buildPagination(pages);if(scroll){var sec=document.querySelector('.nu-recent-news-notice-section');if(sec){var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;sec.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});}}}
function search(){if(!archiveReady)return;var q=searchInput?searchInput.value.trim().toLowerCase():'';filteredRows=allRows.filter(function(r){if(!q)return true;var c=r.cells[0];return (c?c.textContent.toLowerCase():'').indexOf(q)!==-1;});currentPage=1;showPage(1,false);}
if(searchInput)searchInput.addEventListener('input',function(){clearTimeout(searchTimer);searchTimer=setTimeout(search,160);});
if(clearButton)clearButton.addEventListener('click',function(){if(searchInput){searchInput.value='';searchInput.focus();}if(!archiveReady)return;filteredRows=allRows.slice();currentPage=1;showPage(1,false);});
function finish(){filteredRows=allRows.slice();archiveReady=true;showPage(1,false);table.classList.add('nu-pagination-hydrated');if(searchInput&&searchInput.value.trim())search();}
function indexBatch(start){var end=Math.min(start+INDEX_BATCH_SIZE,sourceRows.length);for(var i=start;i<end;i++){var r=sourceRows[i];if(r&&r.cells&&r.cells.length>=3)allRows.push(r);}if(end<sourceRows.length){idle(function(){indexBatch(end);});}else finish();}
function prepare(){sourceRows=Array.prototype.slice.call(tbody.rows);var visible=Math.min(pageSize,sourceRows.length);if(pageInfo)pageInfo.textContent=visible?'Showing 1–'+visible:'0 notices';if(!sourceRows.length){archiveReady=true;table.classList.add('nu-pagination-hydrated');return;}indexBatch(0);}
if(typeof window.requestAnimationFrame==='function'){requestAnimationFrame(function(){requestAnimationFrame(function(){setTimeout(prepare,INITIAL_PREPARE_DELAY);});});}else setTimeout(prepare,INITIAL_PREPARE_DELAY);
})();
</script>


